import numpy as np
import os

# ============================================================
# MULTI-CONFIGURATION SYNTHETIC OBSERVATION SCRIPT
# Generated by DustForge — do not edit directly.
# All {placeholders} are filled by simulate_observation_multiconfig.py
# ============================================================

print('\n##### RUNNING SIMOBSERVE — MULTI-CONFIG #####\n')

os.chdir("{output_dir}")

# ----------------------------------------------------------
# Per-configuration inputs (filled as Python lists by the
# Python driver before this script is passed to CASA)
# ----------------------------------------------------------
project_names    = {project_names}       # list of strings
antennalist_files = {antennalist_files}  # list of paths
integration_times = {integration_times} # list of strings, e.g. "2448s"
pwv_values        = {pwv_values}         # list of floats

central_freq = "{central_freq}Hz"
bandwidth    = "{bandwidth}Hz"

# ----------------------------------------------------------
# Step 1: simobserve for each configuration
# ----------------------------------------------------------
for proj, antlist, ttime, pwv in zip(project_names, antennalist_files, integration_times, pwv_values):
    print(f"\n  --> simobserve: {{proj}}  antennalist={{antlist}}  totaltime={{ttime}}  pwv={{pwv}}")
    simobserve(
        project=proj,
        skymodel="model_image.fits",
        indirection="",
        incell="",
        inbright="",
        incenter=central_freq,
        inwidth=bandwidth,
        antennalist=antlist,
        totaltime=ttime,
        user_pwv=pwv,
        overwrite=True
    )

print('\n##### FIRST-PASS TCLEAN PER CONFIGURATION — RMS ESTIMATION #####\n')

# ----------------------------------------------------------
# Step 2: First-pass tclean per configuration to estimate
#         per-MS RMS, then correct weights (SetWeights).
#         This is critical: simobserve assigns equal weights
#         to all visibilities; the true weight should be
#         1 / (2 * N_vis * sigma^2) where sigma is the
#         thermal noise measured from the image residuals.
# ----------------------------------------------------------

mask          = f"ellipse[[{mask_ra},{mask_dec}], [{mask_semimajor:.3f}arcsec, {mask_semiminor:.3f}arcsec], {PA:.1f}deg]"
noise_annulus = f"annulus[[{mask_ra}, {mask_dec}],['{noise_inner:.3f}arcsec', '{noise_outer:.3f}arcsec']]"

ms_files   = {ms_files}     # list: one .noisy.ms per configuration
cfg_labels = {cfg_labels}   # list: human-readable config labels, e.g. ["C-8","C-6"]
imsize     = {imsize}
cellsize   = {cellsize}     # arcsec (float)
robust     = {robust}
threshold  = {threshold}    # factor × rms

os.makedirs("tclean", exist_ok=True)

def SetWeights(MS_filename, rms_jy):
    """
    Replace simobserve's uniform weights with noise-based weights.
    w = 1 / (2 * N_pol * N_vis * sigma^2)
    This ensures that, when visibilities from multiple configurations
    are concatenated, each baseline contributes proportionally to
    its actual thermal noise rather than an arbitrary equal weight.
    """
    tb.open(MS_filename, nomodify=False)
    weight = tb.getcol("WEIGHT")
    sigma  = tb.getcol("SIGMA")
    nvis   = weight.shape[1]
    weight[:] = 1.0 / (2.0 * nvis * rms_jy**2)
    sigma      = 1.0 / np.sqrt(weight)
    tb.putcol("WEIGHT", weight)
    tb.putcol("SIGMA",  sigma)
    tb.flush()
    tb.close()
    print(f"  SetWeights: {{MS_filename}}  rms={{rms_jy*1e3:.3f}} mJy  weight={{weight.flat[0]:.4e}}")

rms_per_config = []

for ms, cfg in zip(ms_files, cfg_labels):
    image_first = f"tclean/firstclean_{{cfg}}"
    for ext in [".image", ".mask", ".model", ".pb", ".psf", ".residual", ".sumwt", "weight"]:
        os.system(f"rm -rf {{image_first}}{{ext}}")

    tclean(
        vis=ms,
        imagename=image_first,
        datacolumn="data",
        specmode="mfs",
        deconvolver="multiscale",
        scales=[0, 8, 15, 30, 80],
        gridder="standard",
        weighting="briggs",
        robust=robust,
        gain=0.1,
        threshold="0.0Jy",
        cycleniter=300,
        cyclefactor=1,
        imsize=imsize,
        cell=f"{{cellsize:.3f}}arcsec",
        niter=150,
        mask=mask,
        interactive=False,
        savemodel="none",
        nterms=1
    )

    rms_jy = imstat(imagename=image_first + ".image", region=noise_annulus)["rms"][0]
    rms_mJy = rms_jy * 1e3
    print(f"  RMS for {{cfg}}: {{rms_mJy:.3f}} mJy")
    rms_per_config.append(rms_jy)

    SetWeights(ms, rms_jy)

    # Clean up first-pass images
    for ext in [".image", ".mask", ".model", ".pb", ".psf", ".residual", ".sumwt", "weight"]:
        os.system(f"rm -rf {{image_first}}{{ext}}")

print('\n##### CONCATENATING MEASUREMENT SETS #####\n')

# ----------------------------------------------------------
# Step 3: Concatenate all MSes into one combined MS.
#         After SetWeights each MS carries properly scaled
#         weights, so concat just merges the rows.
# ----------------------------------------------------------

concat_dir = "concat_ms"
os.makedirs(concat_dir, exist_ok=True)
concat_vis = f"{{concat_dir}}/{base_name}_concat.ms"
os.system(f"rm -rf {{concat_vis}}")

concat(
    vis=ms_files,
    concatvis=concat_vis,
    copypointing=False
)
listobs(vis=concat_vis, listfile=f"{{concat_dir}}/{base_name}_concat.ms.listobs.txt")
print(f"  Concatenated MS written to: {{concat_vis}}")

print('\n##### JOINT TCLEAN ON CONCATENATED MS #####\n')

# ----------------------------------------------------------
# Step 4: Final joint tclean on the concatenated MS.
#         The threshold is set relative to the combined RMS,
#         estimated as rms_combined ≈ 1/sqrt(sum(1/sigma_i^2))
# ----------------------------------------------------------

rms_combined_jy = 1.0 / np.sqrt(np.sum([1.0 / r**2 for r in rms_per_config]))
rms_combined_mJy = rms_combined_jy * 1e3
threshold_val = threshold * rms_combined_mJy
threshold_str = f"{{threshold_val:.2f}}mJy"
print(f"  Combined RMS estimate: {{rms_combined_mJy:.3f}} mJy")
print(f"  Clean threshold ({threshold}×RMS): {{threshold_str}}")

image_final = f"tclean/{base_name}_multiconfig_robust{robust}_clean"
for ext in [".image", ".mask", ".model", ".pb", ".psf", ".residual", ".sumwt", "weight"]:
    os.system(f"rm -rf {{image_final}}{{ext}}")

tclean(
    vis=concat_vis,
    imagename=image_final,
    datacolumn="data",
    specmode="mfs",
    deconvolver="multiscale",
    scales=[0, 8, 15, 30],
    gridder="standard",
    weighting="briggs",
    robust=robust,
    gain=0.1,
    threshold=threshold_str,
    cycleniter=300,
    cyclefactor=1,
    imsize=imsize,
    cell=f"{{cellsize:.3f}}arcsec",
    niter=50000,
    mask=mask,
    interactive=False,
    savemodel="none",
    nterms=1
)

# Export FITS
exportfits(
    imagename=image_final + ".image",
    fitsimage=image_final + ".image.fits",
    overwrite=True,
    history=True
)

# ----------------------------------------------------------
# Step 5: Measure beam and source statistics
# ----------------------------------------------------------
headerlist    = imhead(image_final + ".image", mode="list")
beammajor     = headerlist["beammajor"]["value"]
beamminor     = headerlist["beamminor"]["value"]
beampa        = headerlist["beampa"]["value"]
target_stats  = imstat(imagename=image_final + ".image", region=mask)
target_flux   = target_stats["flux"][0]
peak_intensity = target_stats["max"][0]
rms_final     = imstat(imagename=image_final + ".image", region=noise_annulus)["rms"][0]
SNR           = peak_intensity / rms_final

configs_str = "+".join(cfg_labels)
with open(f"Info_image_{base_name}_multiconfig_{configs_str}_robust{robust}.txt", "w") as f:
    f.write(f"# {{image_final}}.image\n")
    f.write(f"# Configurations: {{configs_str}}\n")
    f.write(f"# Per-config RMS (mJy): {{[round(r*1e3,3) for r in rms_per_config]}}\n")
    f.write(f"# Combined RMS estimate (mJy): {{rms_combined_mJy:.3f}}\n")
    f.write(f"#\n")
    f.write(f"# Beammajor(arcsec)  Beamminor(arcsec)  PA(deg)  Flux_in_mask(mJy)  Peak_int(mJy/beam)  rms(mJy/beam)  Peak_SNR\n")
    f.write(f"{{beammajor:.3f}}   {{beamminor:.3f}}   {{beampa:.2f}}   {{target_flux*1e3:.2f}}   {{peak_intensity*1e3:.2f}}   {{rms_final*1e3:.2e}}   {{SNR:.2f}}\n")

print(f"\nFinished joint imaging. Beam: {{beammajor:.3f}}\" x {{beamminor:.3f}}\"  SNR: {{SNR:.1f}}")

print('\n##### EXTRACT UVTABLE FROM CONCATENATED MS (for frank) #####\n')

# ----------------------------------------------------------
# Step 6: Export the concatenated MS as an NPZ UV table
#         for frank. We average polarisations with the
#         corrected per-baseline weights set above.
# ----------------------------------------------------------

tb.open(concat_vis)
data   = np.squeeze(tb.getcol("DATA"))
flag   = np.squeeze(tb.getcol("FLAG"))
uvw    = tb.getcol("UVW")
weight = tb.getcol("WEIGHT")
spwid  = tb.getcol("DATA_DESC_ID")
times  = tb.getcol("TIME")
tb.close()

tb.open(concat_vis + "/SPECTRAL_WINDOW")
freqlist = np.squeeze(tb.getcol("CHAN_FREQ"))
if freqlist.ndim == 0:
    freqlist = np.array([freqlist])
tb.close()

# Drop flagged rows
good   = np.squeeze(np.any(flag, axis=0) == False)
data   = data[:, good]
weight = weight[:, good]
uvw    = uvw[:, good]
spwid  = spwid[good]
times  = times[good]

# Polarisation-averaged visibilities with inverse-variance weighting
Re  = np.sum(data.real * weight, axis=0) / np.sum(weight, axis=0)
Im  = np.sum(data.imag * weight, axis=0) / np.sum(weight, axis=0)
vis = Re + 1j * Im
wgt = np.sum(weight, axis=0)

# Map each row to its frequency
get_freq = lambda ispw: freqlist[ispw] if freqlist.ndim > 0 else float(freqlist)
freqs = np.array([get_freq(s) for s in spwid])

um, vm = uvw[0, :], uvw[1, :]
u = um * freqs / 2.9979e8
v = vm * freqs / 2.9979e8

os.makedirs("frank_fit", exist_ok=True)
npz_path = "frank_fit/uvtable_frank_multiconfig.npz"
if os.path.exists(npz_path):
    os.remove(npz_path)
np.savez(npz_path, u=u, v=v, Vis=vis, Wgt=wgt)
print(f"UV table written to {{npz_path}}  ({'{'}len(u){'}'}  visibilities)")
